//! Canonical HTMLElement identity for the fixed semantic HTML names.
//! https://html.spec.whatwg.org/multipage/dom.html#elements-in-the-dom
use super::*;
const TAGS:&str="['abbr','address','article','aside','b','bdi','bdo','cite','code','dd','dfn','dt','em','figcaption','figure','footer','header','hgroup','i','kbd','main','mark','nav','noscript','rp','rt','ruby','s','samp','search','section','small','strong','sub','summary','sup','u','var','wbr']";
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><section id=semantic class=initial></section><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://semantic-html.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn semantic_html_actual_native_factories_and_canonical_prototypes(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("for(var tag of {TAGS}){{var x=document.createElement(tag.toUpperCase());if(Object.getPrototypeOf(x)!==HTMLElement.prototype||x.constructor!==HTMLElement||!(x instanceof HTMLElement)||!(x instanceof Element)||!(x instanceof Node)||x instanceof HTMLUnknownElement||x.localName!==tag||x.namespaceURI!=='http://www.w3.org/1999/xhtml'||x.ownerDocument!==document||Object.prototype.toString.call(x)!=='[object HTMLElement]')throw 'native semantic HTML interface '+tag;}}"));}
#[test]
fn semantic_html_shared_classifier_is_exact(){for tag in ["abbr","address","article","aside","b","bdi","bdo","cite","code","dd","dfn","dt","em","figcaption","figure","footer","header","hgroup","i","kbd","main","mark","nav","noscript","rp","rt","ruby","s","samp","search","section","small","strong","sub","summary","sup","u","var","wbr"]{assert_eq!(crate::javascript::ordinary_html_interface(tag),Some("HTMLElement"),"{tag}");assert_ne!(crate::javascript::ordinary_html_interface(&tag.to_ascii_uppercase()),Some("HTMLElement"),"exact local name {tag}");}}
#[test]
fn semantic_html_inert_explicit_namespace_and_foreign_identity(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var doc=new Document();for(var tag of {TAGS}){{var x=doc.createElementNS('http://www.w3.org/1999/xhtml','t:'+tag),y=doc.createElementNS('urn:foreign',tag),upper=doc.createElementNS('http://www.w3.org/1999/xhtml',tag.toUpperCase());if(Object.getPrototypeOf(x)!==HTMLElement.prototype||x.constructor!==HTMLElement||!(x instanceof HTMLElement)||x instanceof HTMLUnknownElement||x.localName!==tag||x.prefix!=='t'||x.ownerDocument!==doc||y instanceof HTMLElement||y instanceof HTMLUnknownElement||upper.localName!==tag.toUpperCase())throw 'inert semantic exact namespace '+tag;}}"));}
#[test]
fn semantic_html_inherited_attributes_are_actual_exact_handles(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document();for(var x of [document.getElementById('semantic'),doc.createElementNS('http://www.w3.org/1999/xhtml','t:section')]){x.id='before';var a=x.getAttributeNode('id'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x.id='A\ud800Z';var records=watch.takeRecords();if(x.id!=='A\ud800Z'||a.value!==x.id||x.getAttributeNode('id')!==a||records.length!==1||records[0].oldValue!=='before'||Object.getPrototypeOf(x)!==HTMLElement.prototype)throw 'actual semantic attribute';x.removeAttribute('id');if(a.ownerElement!==null||a.value!=='A\ud800Z'||x.id!=='')throw 'semantic attribute removal';}"#);}
#[test]
fn semantic_html_saved_global_and_wrong_concrete_brands(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var C=HTMLElement,P=C.prototype,x=document.getElementById('semantic'),a=Object.getOwnPropertyDescriptor(HTMLFontElement.prototype,'color'),id=Object.getOwnPropertyDescriptor(Element.prototype,'id'),calls=0;delete window.HTMLElement;window.HTMLElement=function Fake(){};for(var y of [x,document.createElement('section'),new Document().createElementNS('http://www.w3.org/1999/xhtml','tt')]){if(!(y instanceof C)||Object.getPrototypeOf(y)!==P||y instanceof window.HTMLElement)throw 'saved semantic canonical interface';var caught=false;try{a.set.call(y,{toString:function(){calls++;return 'bad';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'semantic has no font authority';}for(var bad of [{},Object.create(P)]){var caught=false;try{id.set.call(bad,{toString:function(){calls++;return 'bad';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'semantic prototype grants no native authority';}");}
#[test]
fn semantic_html_captured_origin_refusal_and_recovery(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('semantic'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var C=frame.contentWindow.HTMLElement,a=Object.getOwnPropertyDescriptor(frame.contentWindow.Element.prototype,'id'),calls=0;if(C===HTMLElement||a.get.call(x)!=='semantic')throw 'real child semantic interface';");p.set_location(&crate::navigation::address("https://other-semantic-html.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;for s in ["a.get.call(x);","a.set.call(x,{toString:function(){calls++;return 'bad';}});"]{p.begin_job();let e=p.runtime.execute(s,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}p.set_location(&crate::navigation::address("https://semantic-html.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'semantic origin precedes hooks';a.set.call(x,'recovered');if(a.get.call(x)!=='recovered'||Object.getPrototypeOf(x)!==HTMLElement.prototype)throw 'semantic origin recovery';");}

#[test]
fn semantic_html_native_svg_local_name_has_no_html_authority(){
 let mut d=crate::html::parse("<html><body><svg><font id=foreign></font><rect id=shape></rect></svg></body></html>");
 let node=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("foreign")).unwrap();
 // Explicit native namespace fixture; parser admission is a separate contract.
 d.nodes[node].namespace=crate::html::Namespace::Svg;let shape=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("shape")).unwrap();d.nodes[shape].namespace=crate::html::Namespace::Svg;d.scripting_enabled=true;
 let mut f=Forms::new(&d);let mut p=Page::new();assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);
 {let bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};assert!(bridge.attr_element_receiver(node_handle(node)));assert_eq!(bridge.concrete_html_interface(node_handle(node)),None,"SVG font must not acquire HTMLFontElement authority");}
 run(&mut d,&mut f,&mut p,"var x=document.getElementById('foreign'),a=Object.getOwnPropertyDescriptor(HTMLFontElement.prototype,'color'),calls=0;if(x.namespaceURI!=='http://www.w3.org/2000/svg'||!(x instanceof SVGElement)||x instanceof HTMLElement||Object.getPrototypeOf(x)!==SVGElement.prototype)throw 'actual SVG identity';var caught=false;try{a.get.call(x);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'SVG has no HTML color getter';caught=false;try{a.set.call(x,{toString:function(){calls++;return 'bad';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls||x.hasAttribute('color'))throw 'SVG HTML brand refusal before conversion';var shape=document.getElementById('shape');shape.setAttribute('fill','#112233');if(shape.getAttribute('fill')!=='#112233'||x.hasAttribute('fill')||x.hasAttribute('color'))throw 'real SVG recovery';");
}
